mapper.select:
SELECT a.id, a.user_id, a.category_id, a.title, a.content, a.cover_image, a.view_count, a.like_count, a.comment_count, a.status, a.create_time, a.update_time, u.username, u.nickname, c.name as category_name FROM article a LEFT JOIN user u ON a.user_id = u.id LEFT JOIN category c ON a.category_id = c.id WHERE a.deleted = 0
AND (a.title LIKE CONCAT('%', #{keyword}, '%') OR a.content LIKE CONCAT('%', #{keyword}, '%'))
AND a.category_id = #{categoryId}
AND a.user_id = #{userId}
AND a.status = #{status}
ORDER BY a.create_time DESC
